import "../../styles/index-base.css";
import "../../styles/components/field.css";
import { Field as FieldPrimitive } from "@base-ui/react/field";
import { Fieldset as FieldsetPrimitive } from "@base-ui/react/fieldset";
import type { ComponentPropsWithRef } from "react";
import { cn } from "../../lib/cn";

export type FieldProps = FieldPrimitive.Root.Props;
export type FieldLabelProps = FieldPrimitive.Label.Props;
export type FieldDescriptionProps = FieldPrimitive.Description.Props;
export type FieldErrorProps = FieldPrimitive.Error.Props;
export type FieldControlProps = FieldPrimitive.Control.Props;
export type FieldsetProps = FieldsetPrimitive.Root.Props;
export type FieldsetLegendProps = FieldsetPrimitive.Legend.Props;

export function Field({ className, ...props }: FieldProps) {
  return <FieldPrimitive.Root className={cn("ix-field-layout", className)} {...props} />;
}

export function FieldLabel({ className, ...props }: FieldLabelProps) {
  return <FieldPrimitive.Label className={cn("ix-field-layout__label", className)} {...props} />;
}

export function FieldDescription({ className, ...props }: FieldDescriptionProps) {
  return <FieldPrimitive.Description className={cn("ix-field-layout__description", className)} {...props} />;
}

export function FieldError({ className, match = true, ...props }: FieldErrorProps) {
  return <FieldPrimitive.Error className={cn("ix-field-layout__error", className)} match={match} {...props} />;
}

export function FieldControl({ className, ...props }: FieldControlProps) {
  return <FieldPrimitive.Control className={cn("ix-field-layout__control", className)} {...props} />;
}

export function Fieldset({ className, ...props }: FieldsetProps) {
  return <FieldsetPrimitive.Root className={cn("ix-fieldset", className)} {...props} />;
}

export function FieldsetLegend({ className, ...props }: FieldsetLegendProps) {
  return <FieldsetPrimitive.Legend className={cn("ix-fieldset__legend", className)} {...props} />;
}

export function FieldGroup({ className, ...props }: ComponentPropsWithRef<"div">) {
  return <div className={cn("ix-field-group", className)} {...props} />;
}

/* Generated from src/styles.css. Do not edit directly. */

@layer index.tokens, index.base, index.components;

@layer index.components {
.ix-field-layout {
  display: grid;
  min-width: 0;
  gap: 6px;
}

.ix-field-layout__label,
.ix-fieldset__legend {
  color: var(--ix-fg-default);
  font-size: var(--ix-type-label);
  font-weight: var(--ix-label-weight);
  line-height: var(--ix-line-label);
}

.ix-field-layout__description,
.ix-field-layout__error {
  color: var(--ix-fg-muted);
  font-size: var(--ix-type-metadata);
  line-height: var(--ix-line-metadata);
}

.ix-field-layout__error { color: var(--ix-fg-danger); }

.ix-field-layout__control {
  width: 100%;
  min-width: 0;
  height: var(--ix-control-height-md);
  padding: 0 9px;
  border: 1px solid var(--ix-control-border);
  border-radius: var(--ix-radius-control);
  outline: 0;
  background: var(--ix-bg-control);
  box-shadow: var(--ix-shadow-control);
  color: var(--ix-fg-default);
  font: inherit;
  font-size: var(--ix-type-ui);
  transition: background-color var(--ix-hover-duration), border-color var(--ix-hover-duration), box-shadow var(--ix-hover-duration);
}

.ix-field-layout__control::placeholder { color: var(--ix-fg-subtle); }

.ix-field-layout__control:hover:not(:disabled):not(:read-only) { border-color: var(--ix-control-border-hover); }

.ix-field-layout__control:focus-visible {
  border-color: var(--ix-control-border-hover);
  box-shadow: var(--ix-shadow-control), 0 0 0 2px var(--ix-focus-halo);
}

.ix-field-layout[data-invalid] .ix-field-layout__control,
.ix-field-layout__control[aria-invalid="true"] {
  border-color: color-mix(in oklch, var(--ix-fg-danger) 42%, var(--ix-control-border));
  box-shadow: var(--ix-shadow-control), 0 0 0 2px color-mix(in oklch, var(--ix-fg-danger) 10%, transparent);
}

.ix-field-layout[data-disabled] .ix-field-layout__control,
.ix-field-layout__control:disabled { background: var(--ix-bg-subtle); box-shadow: none; color: var(--ix-fg-disabled); cursor: not-allowed; }

.ix-field-layout__control:read-only { color: var(--ix-fg-muted); }

.ix-fieldset {
  min-width: 0;
  margin: 0;
  padding: 0;
  border: 0;
}

.ix-fieldset__legend { margin: 0 0 8px; padding: 0; }

.ix-field-group { display: grid; gap: 4px; }

@media (prefers-reduced-motion: reduce) {
.ix-field-layout__control { transition-duration: 0.01ms; }
}
}
